```python
from pendulum import parse

vacation_directories = {
    'Athens': [],
    'Seoul': [],
    'Paris': []
}

current_year = parse('now').year

for file in vacation_files:
    created_at = parse(file['created_at'])
    if created_at.month == 1 and created_at.year == current_year:
        vacation_directories['Athens'].append(file)
    elif created_at.month == 4 and created_at.year == current_year:
        vacation_directories['Seoul'].append(file)
    else:
        vacation_directories['Paris'].append(file)

print(f"Athens: {len(vacation_directories['Athens'])} files, Seoul: {len(vacation_directories['Seoul'])} files, Paris: {len(vacation_directories['Paris'])} files")
