Code:
```python
content = movie_recommendations_note['content']
lines = content.split('\n')
movies = []
current_movie = None

for line in lines:
    line = line.strip()
    if not line:
        continue
    if line.startswith('#'):
        continue
    if line.startswith(' - '):
        if current_movie is not None:
            if 'director:' in line:
                director = line.split('director:')[1].strip()
                if 'Peter Jackson' in director:
                    movies.append(current_movie)
    else:
        current_movie = line

# Remove duplicates
movies = list(set(movies))
print(f"Peter Jackson movies: {movies}")
